export type KasaPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function kasaProgram() {
  return <T extends KasaPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { kasa: KasaPlugin }> => {
    return extendClient(client, {
      kasa: <KasaPlugin>{
        accounts: {
          kasa: addSelfFetchFunctions(client, getKasaCodec()),
          loan: addSelfFetchFunctions(client, getLoanCodec()),
          member: addSelfFetchFunctions(client, getMemberCodec()),
        },
        instructions: {
          cancelLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelLoanInstructionAsync(input),
            ),
          collectOverdue: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCollectOverdueInstruction(input),
            ),
          createKasa: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateKasaInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input),
            ),
          disburse: (input) =>
            addSelfPlanAndSendFunctions(client, getDisburseInstruction(input)),
          guarantee: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getGuaranteeInstructionAsync(input),
            ),
          join: (input) =>
            addSelfPlanAndSendFunctions(client, getJoinInstructionAsync(input)),
          pullContribution: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPullContributionInstruction(input),
            ),
          pullInstallment: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPullInstallmentInstruction(input),
            ),
          repay: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRepayInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          requestLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestLoanInstructionAsync(input),
            ),
          setContribution: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetContributionInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
          withdrawGuarantee: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawGuaranteeInstructionAsync(input),
            ),
        },
        pdas: {
          borrowerMember: findBorrowerMemberPda,
          kasa: findKasaPda,
          vault: findVaultPda,
          member: findMemberPda,
          guarantorMember: findGuarantorMemberPda,
        },
        identifyAccount: identifyKasaAccount,
        identifyInstruction: identifyKasaInstruction,
        parseInstruction: parseKasaInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
